# درخواست OPTIONS به یک Endpoint
# پاسخ شامل metadata است

from rest_framework.metadata import SimpleMetadata


class CustomMetadata(SimpleMetadata):
    def determine_metadata(self, request, view):
        metadata = super().determine_metadata(request, view)
        metadata["my_custom_field"] = "مقدار دلخواه"
        metadata["api_version"] = getattr(request, "version", "1.0")
        return metadata


# در تنظیمات
REST_FRAMEWORK = {
    "DEFAULT_METADATA_CLASS": "catalog.metadata.CustomMetadata",
}

# Schema سفارشی برای مدل خاص
from drf_spectacular.extensions import OpenApiSerializerExtension


class CustomSerializerExtension(OpenApiSerializerExtension):
    target_class = "catalog.serializers.CustomSerializer"

    def map_serializer(self, auto_schema, direction):
        return {
            "type": "object",
            "properties": {
                "custom_field": {"type": "string"},
            },
        }


# Schema سفارشی برای فیلد خاص
from drf_spectacular.extensions import OpenApiSerializerFieldExtension
from rest_framework import serializers


class CustomFieldExtension(OpenApiSerializerFieldExtension):
    target_class = "catalog.fields.MyCustomField"

    def map_serializer_field(self, auto_schema, direction):
        return {"type": "string", "format": "custom"}

from drf_spectacular.generators import SchemaGenerator


class CustomSchemaGenerator(SchemaGenerator):
    def get_schema(self, request=None, public=False):
        schema = super().get_schema(request, public)

        # افزودن اطلاعات سازمانی
        schema["info"]["contact"] = {
            "name": "تیم API",
            "email": "api@example.com",
        }
        schema["info"]["x-logo"] = {
            "url": "https://example.com/logo.png",
        }
        return schema


SPECTACULAR_SETTINGS = {
    "DEFAULT_GENERATOR_CLASS": "catalog.schema.CustomSchemaGenerator",
}

