from rest_framework.metadata import SimpleMetadata


class EnhancedMetadata(SimpleMetadata):
    def determine_metadata(self, request, view):
        metadata = super().determine_metadata(request, view)

        metadata["api_version"] = getattr(request, "version", "1.0")

        # فیلدهای read-only
        serializer_class = getattr(view, "serializer_class", None)
        if serializer_class:
            serializer = serializer_class()
            read_only = [
                name for name, field in serializer.fields.items()
                if field.read_only
            ]
            metadata["read_only_fields"] = read_only

        return metadata


REST_FRAMEWORK = {
    "DEFAULT_METADATA_CLASS": "catalog.metadata.EnhancedMetadata",
}
